// Gece lambası: LDR karanlığı ölçer, LED o kadar parlak yanar.
const int ISIK_PIN = A0;   // LDR modülü AO (karanlıkta değer yükselir)
const int LED_PIN = 9;     // PWM pini
const int ESIK = 300;      // bunun altı "aydınlık": LED söner

void setup() {
  Serial.begin(9600);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  int karanlik = analogRead(ISIK_PIN);        // 0-1023
  int parlaklik = 0;
  if (karanlik > ESIK) parlaklik = map(karanlik, ESIK, 1023, 20, 255);
  analogWrite(LED_PIN, parlaklik);
  Serial.print("Karanlik: ");
  Serial.print(karanlik);
  Serial.print("  Parlaklik: ");
  Serial.println(parlaklik);
  delay(200);
}
